// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"cryptocurrency":{"slug":"cryptocurrency","cat":"basics","en":"Cryptocurrency","contentLocale":"en","term":"Cryptocurrency","aka":["crypto","digital currency","crypto asset"],"short":"A cryptocurrency is a digital asset that is issued and transferred on a blockchain, secured by cryptography instead of a bank or central authority.","body":[["Ownership of a cryptocurrency is recorded on a public ",["blockchain","blockchain"],". What you actually hold is a ",["private key","private-key"],", a secret number that lets you sign transactions moving coins from your address. Whoever controls the key controls the coins, which is why exchanges and wallets put so much effort into key security."],["The word covers very different assets. ",["Bitcoin","bitcoin"]," is designed as scarce digital money with a fixed 21 million supply. Ether pays for computation on ",["Ethereum","ethereum"],". ",["Stablecoins","stablecoin"]," such as ",["USDT","usdt"]," and USDC aim to track the US dollar. Thousands of other tokens represent projects, governance rights or simply internet culture, as with memecoins."],"Prices are set by trading on exchanges around the clock, every day of the year. That means crypto can move sharply at night or over a weekend, and price swings of 5 to 10 percent in a day are common for many coins. How crypto is taxed and regulated depends on your country, so rules that apply to a friend abroad may not apply to you."],"example":"Suppose you deposit 500 USDT on an exchange and buy ETH at 2,500 USDT per coin. You receive 0.2 ETH, minus a small trading fee. If ETH later trades at 2,750 USDT, your 0.2 ETH is worth 550 USDT, a 10 percent gain before fees. If it falls to 2,250 USDT, the same holding is worth 450 USDT. The number of coins you own stays at 0.2 ETH; only their price in dollars changes.","mistakes":["Treating all cryptocurrencies as interchangeable when a stablecoin, Bitcoin and a new memecoin carry completely different risks.","Sharing a seed phrase or private key with someone who claims to be support staff.","Buying a coin because its unit price looks cheap, without checking its total supply and market capitalization."],"faq":[{"q":"Is cryptocurrency real money?","a":"Some countries treat certain cryptocurrencies as legal property or payment methods, while others restrict them. In practice, crypto has value because people are willing to trade it, and it can be exchanged for local currency on exchanges."},{"q":"What was the first cryptocurrency?","a":"Bitcoin, launched in January 2009 by the pseudonymous Satoshi Nakamoto, was the first widely used cryptocurrency."},{"q":"Do I need to buy a whole coin?","a":"No. Most cryptocurrencies are divisible. You can buy 0.001 BTC or 10 USDT worth of a coin on most exchanges."}],"title":"What is cryptocurrency? Meaning explained simply","description":"Understand what cryptocurrency is, how ownership and private keys work, and why prices move around the clock.","related":[["blockchain","Blockchain","A blockchain is a shared digital ledger, copied across many computers, where transactions are grouped into blocks that are linked in order and are extremely hard to change after the fact."],["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) is the first cryptocurrency, a decentralized digital money with a hard cap of 21 million coins that runs on its own proof-of-work blockchain."],["altcoin","Altcoin","An altcoin is any cryptocurrency other than Bitcoin, a broad category that includes Ether, Solana, stablecoins, exchange tokens and memecoins."],["stablecoin","Stablecoin","A stablecoin is a cryptocurrency designed to keep a steady value, usually 1 US dollar, by being backed by reserves such as cash and treasury bills, by crypto collateral, or by other mechanisms."],["centralized-exchange","Centralized exchange (CEX)","A centralized exchange (CEX) is a company-run trading platform where you deposit funds into an account and trade crypto through the exchange's order book, with the company holding custody of your assets."]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"One bitcoin costs that much. Can I still buy some?"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"smart-contract":{"slug":"smart-contract","cat":"basics","en":"Smart contract","contentLocale":"en","term":"Smart contract","aka":["contract","on-chain contract"],"short":"A smart contract is a program stored on a blockchain that runs automatically when its conditions are met, letting people trade, lend or issue tokens without a middleman.","body":[["A smart contract holds code and often holds funds. When you interact with it, for example by swapping tokens on a ",["decentralized exchange","dex"],", every ",["node","node"]," runs the same code and records the result. Nobody can quietly change the outcome, and the contract keeps working as long as the ",["blockchain","blockchain"]," runs."],[["Ethereum","ethereum"]," made smart contracts popular, and today most major chains support them. ",["Stablecoins","stablecoin"],", ERC20 tokens, lending protocols, ",["NFT","nft"]," collections and liquid staking all run on smart contracts. Each interaction costs a gas fee paid to the network."],"\"Code is law\" cuts both ways. If a contract has a bug, attackers can exploit it and funds may be lost with no bank to reverse it. Some contracts are upgradeable, which means an admin key can change the code. Audits reduce risk but do not remove it. Before you approve a contract to spend your tokens, make sure it is the official address."],"example":"Suppose a lending contract lets you deposit 1 ETH as collateral and borrow up to 70 percent of its value in USDC. With ETH at 2,000 USDC, you can borrow up to 1,400 USDC. You borrow 1,000 USDC. If ETH falls to 1,500 USDC, your collateral is worth 1,500 and your loan is 1,000, about 67 percent of the collateral. If the protocol's liquidation threshold is 75 percent and ETH drops further to about 1,333 USDC, the contract can automatically sell part of your ETH to repay the loan, with no human approval needed.","mistakes":["Approving unlimited token spending for a contract you found through a random link or airdrop.","Assuming an audited contract cannot be hacked.","Interacting with a copycat contract that has the same token name but a different address."],"faq":[{"q":"Are smart contracts legally binding?","a":"Not by themselves. They are code that executes automatically. Whether they create legal obligations depends on the situation and the country."},{"q":"Can a smart contract be changed?","a":"Some are immutable once deployed. Others use an upgradeable design that lets an admin or governance vote replace the code, which you can usually check in the project documentation or block explorer."},{"q":"Which blockchains support smart contracts?","a":"Ethereum and its layer 2 networks, BNB Chain, Solana, Avalanche, Tron and many others support smart contracts. Bitcoin's scripting is far more limited."}],"title":"What is a smart contract? Meaning with an example","description":"Learn what a smart contract is, how it runs on a blockchain and the risks of bugs, upgrades and token approvals.","related":[["ethereum","Ethereum (ETH)","Ethereum is a programmable blockchain that runs smart contracts, and Ether (ETH) is its native coin used to pay gas fees and to stake for network security."],["defi","DeFi (decentralized finance)","DeFi, short for decentralized finance, is a set of financial services such as trading, lending and earning yield that run on public blockchains through smart contracts instead of through banks or exchanges."],["token-approval","Token approval (allowance)","A token approval is a permission you sign in your wallet that lets a smart contract spend a set amount of a specific token from your address, often needed before swapping or depositing in DeFi."],["oracle","Blockchain oracle","A blockchain oracle is a service that brings outside data, most often asset prices, onto a blockchain so smart contracts can use it for actions like liquidations, settlements and swaps."],["gas-fee","Gas fee","A gas fee is the payment you make to a blockchain network to process a transaction or run a smart contract, paid in the chain's native coin such as ETH on Ethereum."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"gas-fee":{"slug":"gas-fee","cat":"basics","en":"Gas fee","contentLocale":"en","term":"Gas fee","aka":["gas","network fee","transaction fee"],"short":"A gas fee is the payment you make to a blockchain network to process a transaction or run a smart contract, paid in the chain's native coin such as ETH on Ethereum.","body":[["On ",["Ethereum","ethereum"]," and similar chains, every operation consumes a set amount of gas units. A simple ETH transfer uses 21,000 units, while a token swap might use 100,000 to 200,000. You pay the number of units multiplied by the gas price, quoted in gwei, where 1 gwei equals 0.000000001 ETH."],["Since 2021, Ethereum's fee has two parts: a base fee that the protocol burns and a priority fee, or tip, that goes to the ",["validator","validator"],". When the network is busy, the base fee rises automatically. If you set a gas limit too low, the transaction can fail and you still pay for the work done."],["Gas fees differ widely between networks. Layer 2s and chains like Solana or Tron are usually much cheaper than Ethereum mainnet. When you withdraw from an exchange, you usually pay the exchange's fixed ",["withdrawal fee","withdrawal-fee"]," instead, which it uses to cover gas, so it can differ from the live network cost."]],"example":["Suppose you send ",["USDT","usdt"]," on Ethereum, which uses about 65,000 gas units, when the gas price is 30 gwei. The fee is 65,000 x 30 = 1,950,000 gwei, or 0.00195 ETH. With ETH at 3,200 USDT, that costs about 6.24 USDT. If you waited until the gas price dropped to 10 gwei, the same transfer would cost 0.00065 ETH, about 2.08 USDT."],"mistakes":["Leaving a wallet with tokens but no native coin to pay gas.","Lowering the gas limit to save money and having the transaction fail, still paying for the attempt.","Sending a small amount over Ethereum mainnet when the fee is a big share of the transfer."],"faq":[{"q":"Why are gas fees so high sometimes?","a":"Block space is limited. When many people want to transact at once, such as during a popular token launch or a market crash, the base fee rises until demand cools."},{"q":"Do I get my gas back if a transaction fails?","a":"Usually not. The network still used resources to process the failed transaction, so the gas spent is lost."},{"q":"Is a withdrawal fee the same as a gas fee?","a":"Not exactly. An exchange withdrawal fee is set by the exchange to cover on-chain costs and may be higher or lower than the live gas fee."}],"title":"What is a gas fee in crypto? Meaning and how to calculate","description":"Learn what gas fees are, how gwei and gas limits work and why fees differ between Ethereum, layer 2s and other chains.","related":[["layer-2","Layer 2 (L2)","A layer 2 (L2) is a network built on top of a layer 1 blockchain that processes transactions off the main chain and posts the results back to it, giving lower fees while borrowing much of the L1's security."],["mempool","Mempool","The mempool is the waiting area where valid but unconfirmed transactions sit on network nodes until a miner or validator includes them in a block."],["withdrawal-fee","Withdrawal fee","A withdrawal fee is the amount an exchange charges when you send crypto from your account to an external address, usually to cover the blockchain network fee."],["ethereum","Ethereum (ETH)","Ethereum is a programmable blockchain that runs smart contracts, and Ether (ETH) is its native coin used to pay gas fees and to stake for network security."],["smart-contract","Smart contract","A smart contract is a program stored on a blockchain that runs automatically when its conditions are met, letting people trade, lend or issue tokens without a middleman."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Before you transfer: don't guess any of these"},"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"bull-market":{"slug":"bull-market","cat":"basics","en":"Bull market","contentLocale":"en","term":"Bull market","aka":["bull run","bullish market"],"short":"A bull market is a sustained period when prices rise broadly and investor confidence is high, commonly described as a gain of 20 percent or more from a recent low.","body":[["The term comes from the way a bull attacks, thrusting its horns upward. In crypto, bull markets tend to be faster and more extreme than in stocks. ",["Bitcoin","bitcoin"]," often leads, and altcoins and memecoins frequently follow with bigger moves later in the cycle."],["Typical signs include rising prices on higher ",["trading volume","trading-volume"],", new all-time highs, positive funding rates on ",["perpetual futures","perpetual-futures"],", record exchange sign-ups and heavy social media attention. Sentiment gauges such as the ",["Fear and Greed Index","fear-and-greed-index"]," often sit in the greed zone for long stretches."],["Bull markets are not straight lines. Pullbacks of 20 to 30 percent inside a crypto bull market have been common, and ",["leverage","leverage"]," that looks safe while prices rise can be wiped out in one sharp correction. Nobody can reliably tell in real time whether a bull market is starting or ending, so a written plan for entries, exits and ",["position size","position-sizing"]," is more useful than predictions."]],"example":"Suppose a coin rises from 20 to 50 USDT over six months, a 150 percent gain. Along the way it drops from 40 to 30 USDT in a week, a 25 percent pullback, before recovering. A trader who bought at 40 with 5x leverage and isolated margin would likely have been liquidated during that dip, even though the coin later reached 50. A spot holder who sized the position modestly could simply wait it out.","mistakes":["Increasing leverage as prices rise because recent trades worked.","Assuming every dip in a bull market will recover quickly.","Buying coins only because they are trending on social media, late in a big move."],"faq":[{"q":"How long does a crypto bull market last?","a":"There is no fixed length. Past crypto bull markets have lasted from several months to more than a year, and every cycle has had different drivers."},{"q":"What does bullish mean?","a":"Bullish means expecting prices to rise. A trader who is bullish on BTC thinks its price will go up."},{"q":"What is the opposite of a bull market?","a":"A bear market, a sustained period of falling prices and weak sentiment."}],"title":"What is a bull market in crypto? Meaning and signs","description":"Learn what a crypto bull market is, the common signs traders watch and why pullbacks still hit leveraged positions.","related":[["bear-market","Bear market","A bear market is a sustained period of falling prices and pessimistic sentiment, commonly described as a decline of 20 percent or more from a recent high."],["fomo","FOMO","FOMO, or fear of missing out, is the anxious urge to buy an asset after its price has already risen sharply, driven by the worry that others are profiting without you."],["all-time-high","All-time high (ATH)","An all-time high (ATH) is the highest price an asset has ever reached in its trading history, and the opposite, the lowest price ever, is called an all-time low (ATL)."],["fear-and-greed-index","Fear and Greed Index","The Fear and Greed Index is a sentiment gauge that combines market data such as volatility, momentum and social activity into a single score from 0 (extreme fear) to 100 (extreme greed)."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"take-profit":{"slug":"take-profit","cat":"trading","en":"Take-profit order","contentLocale":"en","term":"Take-profit order","aka":["take profit","TP"],"short":"A take-profit order is an order that automatically closes all or part of your position when the price reaches a target level, locking in gains without you having to watch the market.","body":[["For a long position, the take-profit sits above your entry; for a short, below it. When the trigger is hit, the exchange closes the position with a market or ",["limit order","limit-order"],". On futures, take-profit and stop-loss can often be attached to the position directly when you open it."],"Take-profit targets help you follow a plan instead of reacting to emotion. Many traders set targets at previous highs, resistance levels or a multiple of their risk, such as two or three times the distance to their stop-loss. Some scale out, closing half at a first target and the rest at a second.","The trade-off is that a take-profit caps your upside on that portion if the price keeps running. In fast markets, a market-triggered take-profit can fill slightly differently from the trigger, and a limit take-profit might be skipped if the price spikes through and reverses."],"example":["Suppose you buy 1 ",["ETH","ethereum"]," at 2,000 ",["USDT","usdt"]," with a stop-loss at 1,900, risking 100 USDT. You set two take-profits: half at 2,200 and half at 2,300. If ETH reaches 2,200, you lock in 100 USDT on the first 0.5 ETH. If it then reaches 2,300, the second half adds 150 USDT, for a total of 250 USDT before fees, a reward of 2.5 times the 100 USDT you risked."],"mistakes":["Setting take-profit targets so close that fees and spread eat most of the gain.","Removing a take-profit during a rally out of greed, then watching the price fall back.","Forgetting that a full take-profit closes the whole position, leaving no exposure if the trend continues."],"faq":[{"q":"How do I set a take-profit?","a":"Choose a target based on your analysis, such as a resistance level or a risk multiple, and attach the order when you open the position or add it afterwards."},{"q":"Should I use take-profit and stop-loss together?","a":"Many traders do, so both outcomes are planned. Some exchanges let you link them as an OCO order, where one cancels the other."},{"q":"What is TP in crypto trading?","a":"TP is short for take-profit, the price where you plan to close a position with a gain."}],"title":"What is a take-profit order? Meaning in crypto trading","description":"Learn how take-profit orders lock in gains, how to set targets and how scaling out with partial take-profits works.","related":[["stop-loss","Stop-loss order","A stop-loss order is an order that automatically closes your position when the price reaches a level you set, limiting how much you can lose on a trade."],["oco-order","OCO order (one-cancels-the-other)","An OCO (one-cancels-the-other) order pairs two orders, typically a take-profit and a stop-loss, so that when one of them executes, the other is automatically cancelled."],["risk-reward-ratio","Risk-reward ratio","The risk-reward ratio compares how much you could lose on a trade, up to your stop-loss, with how much you could gain, up to your take-profit target."],["limit-order","Limit order","A limit order is an instruction to buy or sell only at a specific price or better, so a buy limit fills at your price or lower and a sell limit fills at your price or higher."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Take-profit and stop-loss are plans, not insurance"},"coin":null,"tool":null,"cta":false},"margin-trading":{"slug":"margin-trading","cat":"derivatives","en":"Margin trading","contentLocale":"en","term":"Margin trading","aka":["trading on margin","spot margin"],"short":"Margin trading is trading with funds borrowed from an exchange, using your own assets as collateral, so you can open larger positions or short-sell.","body":[["In spot margin trading you borrow coins or ",["stablecoins","stablecoin"]," from the exchange and pay interest, usually charged hourly or daily. Borrowing ",["USDT","usdt"]," lets you buy more of a coin than your balance allows. Borrowing a coin and selling it lets you go short. In futures, margin works as collateral for a ",["contract","smart-contract"]," rather than an actual loan, but the idea of trading a larger position on collateral is the same."],["Your collateral must stay above a minimum level, known as the ",["maintenance margin","maintenance-margin"],". If losses push your margin level below it, the exchange may issue a warning, often called a ",["margin call","margin-call"],", and then liquidate your position to repay the loan."],["Exchanges offer different margin modes. ",["Isolated margin","isolated-margin"]," limits risk to the collateral assigned to one position. Cross margin shares your whole balance across positions. Interest rates, borrowable coins and maximum leverage vary by exchange and change with demand, so check them before you borrow."]],"example":"Suppose you have 2,000 USDT and use 3x spot margin to buy BTC at 40,000 USDT. You borrow 4,000 USDT and buy 0.15 BTC worth 6,000 USDT. If BTC rises to 44,000, the BTC is worth 6,600 USDT; after repaying 4,000 you keep 2,600, a 30% gain on your capital before interest. If BTC falls to 36,000, you keep 5,400 − 4,000 = 1,400, a 30% loss.","mistakes":["Forgetting borrowing interest, which keeps accruing while a position stays open.","Assuming margin trading is the same as futures, when spot margin involves a real loan.","Using cross margin without realising that one losing position can drain the whole balance."],"faq":[{"q":"What is the difference between margin trading and futures?","a":"Spot margin uses a real loan to buy or sell the actual coin, with interest. Futures are contracts on the price, with funding or a basis instead of borrowing interest."},{"q":"How does margin trading let you short a coin?","a":"You borrow the coin, sell it, and later buy it back to repay the loan. If the price fell in between, you keep the difference minus interest."}],"title":"What is margin trading in crypto? How it works","description":"Learn how crypto margin trading works, how borrowing and collateral amplify results and what triggers a margin call.","related":[["leverage","Leverage","Leverage is using borrowed funds or margin to open a position larger than your own capital, which multiplies both profits and losses."],["initial-margin","Initial margin","Initial margin is the amount of collateral you must post to open a leveraged position, usually equal to the position value divided by your leverage."],["maintenance-margin","Maintenance margin","Maintenance margin is the minimum collateral you must keep in a leveraged position; if your margin falls below it, the position is liquidated."],["liquidation","Liquidation","Liquidation is when an exchange forcibly closes your leveraged position because your margin has fallen below the maintenance margin requirement."],["cross-margin","Cross margin","Cross margin is a margin mode where all your open positions share the available balance in your account as collateral, so profits and spare funds can absorb losses before liquidation."]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"10x leverage: more money, or more risk?"},"coin":null,"tool":null,"cta":false},"non-custodial-wallet":{"slug":"non-custodial-wallet","cat":"wallets-security","en":"Non-custodial (self-custody) wallet","contentLocale":"en","term":"Non-custodial wallet (self-custody wallet)","aka":["self-custody wallet","self-custodial wallet","non-custodial wallet"],"short":"A non-custodial wallet is a crypto wallet where you alone hold the private keys or seed phrase, so no exchange or company can move, freeze or recover your funds for you.","body":[["With a non-custodial wallet, the wallet app or device only helps you create and use keys. The keys themselves stay with you, usually backed up as a 12- or 24-word ",["seed phrase","seed-phrase"],". Whoever has that phrase controls the coins, which is why the phrase matters more than the app."],"This is the opposite of keeping coins on an exchange, where the platform holds the keys and you hold a balance in its database. Self-custody removes the risk of an exchange freezing withdrawals or failing, but it moves all the responsibility to you: there is no password reset and no support desk that can reverse a mistaken transfer.","Common examples are browser and mobile wallets such as MetaMask, Phantom or Trust Wallet, and hardware wallets such as Ledger or Trezor. Some exchanges also offer a separate self-custody wallet app alongside their main exchange account; check which mode you are using before you assume who holds the keys."],"example":["Suppose you buy 0.2 ",["BTC","bitcoin"]," on an exchange and withdraw it to a new non-custodial wallet. The wallet shows you 12 words once, and you write them on paper. A year later your phone breaks. You install the wallet on a new phone, type the same 12 words in the same order, and the 0.2 BTC reappears, because the coins live on the ",["blockchain","blockchain"]," and the words regenerate the keys. If you had lost the paper as well, nobody could restore access."],"mistakes":["Saving the seed phrase as a screenshot or in cloud notes, where malware or a hacked account can read it.","Assuming the wallet company can recover funds after you lose the seed phrase.","Moving a large balance before doing a small test transfer and a test restore of the backup."],"faq":[{"q":"Is a non-custodial wallet safer than an exchange?","a":"It removes exchange risk, such as frozen withdrawals or insolvency, but adds personal risk, such as losing your seed phrase or signing a malicious transaction. It is safer only if you manage the keys carefully."},{"q":"Is MetaMask a non-custodial wallet?","a":"Yes. MetaMask generates keys on your device and never holds your seed phrase, so only you can sign transactions from it."},{"q":"What happens if the wallet app shuts down?","a":"Your funds stay on the blockchain. You can import the same seed phrase into another compatible wallet and keep access."}],"title":"What is a non-custodial wallet? Self-custody explained","description":"Learn what a non-custodial wallet is, how self-custody works, and what you are responsible for when you hold your own keys.","related":[["custodial-wallet","Custodial wallet","A custodial wallet is a crypto wallet where a third party, usually an exchange or app, holds the private keys and controls the funds on your behalf."],["seed-phrase","Seed phrase (recovery phrase)","A seed phrase is a list of usually 12 or 24 ordinary words that encodes the master key of a crypto wallet, so anyone who has the words can restore the wallet and spend all of its funds."],["private-key","Private key","A private key is a secret number that proves ownership of a crypto address and is used to sign transactions, so whoever holds it can spend the coins at that address."],["hardware-wallet","Hardware wallet","A hardware wallet is a small physical device that stores your private keys offline and signs transactions inside the device, so the keys never leave it even when it is plugged into a computer or phone."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Where are my coins? Exchange vs wallet"},"coin":null,"tool":null,"cta":false},"multisig-wallet":{"slug":"multisig-wallet","cat":"wallets-security","en":"Multisig wallet","contentLocale":"en","term":"Multisig wallet","aka":["multisignature wallet","multi-sig","Safe wallet"],"short":"A multisig wallet is a crypto wallet that needs signatures from several separate keys, such as 2 of 3, before any transaction can be sent, so no single lost or stolen key can move the funds.","body":[["A multisig is described as M-of-N: N keys exist and M of them must sign. A 2-of-3 setup can survive one lost key and still blocks a thief who steals one key. On ",["Bitcoin","bitcoin"],", multisig is built into the script system. On ",["Ethereum","ethereum"]," and EVM chains, it is usually a ",["smart contract","smart-contract"]," wallet, with Safe as a widely used example."],["Multisigs are standard for ",["DAO","dao"]," treasuries, company funds and exchange ",["cold storage","cold-wallet"],". Individuals use them for large savings, often with keys on different hardware wallets stored in different places."],"The trade-off is complexity. You must back up every key and, for Bitcoin, the wallet configuration that describes the setup. Each transaction takes more steps, and on EVM chains you rely on the multisig contract being secure."],"example":["Suppose a small team keeps 120,000 ",["USDC","usdc"]," in a 2-of-3 Safe. Each of three founders holds one key on a separate hardware wallet. One founder's laptop is compromised and the attacker proposes sending everything to their address. The other two founders see the proposal, refuse to sign, and move the funds to a new Safe with a replacement key. With a single-key wallet, the 120,000 USDC would already be gone."],"mistakes":["Storing two of the three keys in the same place, which turns 2-of-3 into a single point of failure.","Backing up the keys but not the Bitcoin wallet configuration needed to rebuild the multisig.","Signing a multisig transaction without checking what the other signer proposed."],"faq":[{"q":"Is a multisig wallet worth it for individuals?","a":"For large long-term holdings it can be, because it removes single points of failure. For small amounts the extra complexity is often not worth it."},{"q":"What happens if one multisig key is lost?","a":"In an M-of-N setup, you can still sign with the remaining keys as long as you have at least M. Replace the lost key soon by moving funds to a new setup."}],"title":"What is a multisig wallet? M-of-N explained","description":"Learn how a multisig wallet works, why 2-of-3 setups protect funds, and the backup mistakes that defeat multisig.","related":[["private-key","Private key","A private key is a secret number that proves ownership of a crypto address and is used to sign transactions, so whoever holds it can spend the coins at that address."],["cold-wallet","Cold wallet (cold storage)","A cold wallet is a way of storing crypto where the private keys are generated and kept offline, away from internet-connected devices, so remote attackers cannot reach them."],["dao","DAO (decentralized autonomous organization)","A DAO, or decentralized autonomous organization, is a community that makes decisions and manages a shared treasury through token-holder voting and smart contracts instead of a traditional management structure."],["non-custodial-wallet","Non-custodial wallet (self-custody wallet)","A non-custodial wallet is a crypto wallet where you alone hold the private keys or seed phrase, so no exchange or company can move, freeze or recover your funds for you."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Where are my coins? Exchange vs wallet"},"coin":null,"tool":null,"cta":false},"dao":{"slug":"dao","cat":"defi","en":"DAO (decentralized autonomous organization)","contentLocale":"en","term":"DAO (decentralized autonomous organization)","aka":["DAO","decentralized autonomous organisation"],"short":"A DAO, or decentralized autonomous organization, is a community that makes decisions and manages a shared treasury through token-holder voting and smart contracts instead of a traditional management structure.","body":[["Members propose changes, such as adjusting protocol fees, funding a grant or upgrading a ",["contract","smart-contract"],". Holders of the ",["governance token","governance-token"]," vote, and if a proposal passes, a smart contract or a multisig carries it out. Uniswap, Aave and MakerDAO, now Sky, are examples of protocols governed this way."],"In practice, DAOs mix on-chain and off-chain steps. Discussion often happens on forums, early votes run on gasless tools such as Snapshot, and execution may rely on a multisig of trusted signers. How decentralized a DAO really is depends on who holds the tokens and who controls the keys.","Common problems include low voter turnout, voting power concentrated among large holders or the team, and governance attacks where someone acquires enough tokens to pass a harmful proposal."],"example":["Imagine a DAO with 100 million governance tokens and a quorum of 4 million votes. A proposal to spend 500,000 ",["USDC","usdc"]," from the treasury on a security audit receives 5.2 million yes votes and 0.8 million no votes. It meets quorum and passes. After a two-day timelock, the treasury contract sends the 500,000 USDC to the auditor. If only 3 million votes had been cast, it would have failed despite a yes majority."],"mistakes":["Assuming a project is decentralized just because it calls itself a DAO.","Believing governance tokens give a share of profits; many give only voting rights.","Ignoring how much voting power the team and early investors hold."],"faq":[{"q":"How do you join a DAO?","a":"Usually by holding its governance token. Some DAOs also use NFTs or membership approval."},{"q":"Is a DAO legally a company?","a":"It depends on the country. Some jurisdictions offer legal wrappers for DAOs, while others treat members in different ways."}],"title":"What is a DAO? Decentralized organizations explained","description":"Learn what a DAO is, how proposals and token voting work, and why decentralization varies from one DAO to another.","related":[["governance-token","Governance token","A governance token is a crypto token that gives holders the right to vote on a protocol's decisions, such as fee changes, upgrades and treasury spending, in proportion to the tokens they hold or delegate."],["multisig-wallet","Multisig wallet","A multisig wallet is a crypto wallet that needs signatures from several separate keys, such as 2 of 3, before any transaction can be sent, so no single lost or stolen key can move the funds."],["smart-contract","Smart contract","A smart contract is a program stored on a blockchain that runs automatically when its conditions are met, letting people trade, lend or issue tokens without a middleman."],["defi","DeFi (decentralized finance)","DeFi, short for decentralized finance, is a set of financial services such as trading, lending and earning yield that run on public blockchains through smart contracts instead of through banks or exchanges."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"apr-vs-apy":{"slug":"apr-vs-apy","cat":"defi","en":"APR vs APY","contentLocale":"en","term":"APR vs APY","aka":["APR","APY","annual percentage rate","annual percentage yield"],"short":"APR is the simple annual rate of return or interest without compounding, while APY includes the effect of reinvesting earnings, so APY is higher than APR whenever returns compound.","body":["APR, annual percentage rate, multiplies a periodic rate by the number of periods in a year. APY, annual percentage yield, assumes each payout is added back and earns returns of its own. The formula is APY equals (1 plus APR divided by n) to the power of n, minus 1, where n is the number of compounding periods.","The difference grows with higher rates and more frequent compounding. At 5 percent APR, daily compounding gives about 5.13 percent APY. At 100 percent APR, daily compounding gives about 171 percent APY, a number that looks much more exciting.","Crypto platforms use both terms, sometimes inconsistently. Check which one is shown, whether compounding is automatic, whether the rate is fixed or variable, and what currency the reward is paid in. A variable rate shown as APY assumes it stays the same all year, which is rare."],"example":["Suppose a product pays 12 percent APR on 1,000 ",["USDT","usdt"]," with daily payouts. Without reinvesting, you earn 120 USDT in a year. If each day's interest is added to your balance, APY is (1 plus 0.12 divided by 365) to the power of 365, minus 1, about 12.75 percent, so you end with about 1,127.47 USDT. The extra 7.47 USDT comes only from compounding."],"mistakes":["Comparing one product's APY with another's APR as if they were the same measure.","Assuming a high variable APY will hold for a full year.","Forgetting that rewards paid in a different token add price risk to the stated rate."],"faq":[{"q":"Is APY better than APR?","a":"Neither is better; they measure different things. For the same underlying rate, APY is higher because it includes compounding."},{"q":"How do I convert APR to APY?","a":"Use APY equals (1 plus APR divided by n) to the power of n, minus 1, where n is how many times per year earnings compound."}],"title":"APR vs APY in crypto: what is the difference?","description":"Learn the difference between APR and APY, how compounding changes your yield, and how to compare crypto earn rates fairly.","related":[["staking","Staking","Staking is locking up coins of a proof-of-stake blockchain to help validate transactions and secure the network, in return for staking rewards paid in that coin."],["yield-farming","Yield farming","Yield farming is the practice of moving crypto into DeFi protocols, such as liquidity pools or lending markets, to earn trading fees, interest and extra token rewards."],["crypto-earn","Crypto Earn (savings products)","Crypto Earn refers to exchange savings products that pay you a yield for depositing crypto, either flexible with withdrawal anytime or locked for a fixed term."],["funding-rate","Funding rate","A funding rate is a periodic payment between long and short traders that keeps a perpetual futures price close to the spot price."]],"lesson":null,"coin":null,"tool":null,"cta":false},"algorithmic-stablecoin":{"slug":"algorithmic-stablecoin","cat":"stablecoins","en":"Algorithmic stablecoin","contentLocale":"en","term":"Algorithmic stablecoin","aka":["algo stablecoin","algostable"],"short":"An algorithmic stablecoin is a stablecoin that tries to hold its peg mainly through code-driven supply changes and incentives rather than full reserves of cash or collateral.","body":[["Most ",["stablecoins","stablecoin"]," are backed by dollars, short-term bonds or crypto collateral. An algorithmic stablecoin relies instead on rules: when the price is above 1 USD, the protocol expands supply; when it is below, it tries to shrink supply, often by letting users burn the stablecoin in exchange for a second, volatile token."],"This works while people trust the system and the companion token keeps its value. In a panic, the loop can reverse. Holders redeem the stablecoin for the companion token, flood the market with it, its price falls, and each redemption needs even more new tokens. This is often called a death spiral.","TerraUSD (UST) is the textbook case: in May 2022 it lost its peg and its companion token LUNA collapsed toward zero within days. Since then, many projects call themselves hybrid or partially collateralized, so read how much hard backing actually exists before you treat a coin as cash."],"example":["Imagine an algorithmic stablecoin trades at 0.97 USD. The protocol lets you burn 1 stablecoin for 1 USD worth of its ",["governance token","governance-token"],", so arbitrageurs buy at 0.97, redeem, and earn about 3% if they can sell the governance token at full value. But if 50 million stablecoins are redeemed while the governance token's ",["market cap","market-capitalization"]," is only 200 million USD, the new supply equals a quarter of its value, its price drops, and the next redemptions mint even more tokens."],"mistakes":["Treating a high advertised yield on an algorithmic stablecoin as low risk because the coin is called stable.","Ignoring the size and liquidity of the companion token that is supposed to absorb redemptions.","Assuming a coin labelled hybrid has full backing without checking the actual reserve ratio."],"faq":[{"q":"Are algorithmic stablecoins safe?","a":"They carry more risk than fully backed stablecoins because the peg depends on market confidence and incentives. The UST collapse in 2022 showed how quickly a design can fail under stress."},{"q":"What is the difference between algorithmic and crypto-backed stablecoins?","a":"A crypto-backed stablecoin holds collateral worth more than its supply. An algorithmic stablecoin relies mainly on supply rules and arbitrage incentives, with little or no hard backing."}],"title":"What is an algorithmic stablecoin? Meaning and risks","description":"What an algorithmic stablecoin is, how supply rules try to hold the peg, and why designs like UST collapsed in a death spiral.","related":[["depeg","Depeg","A depeg is when a stablecoin or pegged token trades meaningfully away from the value it is designed to track, such as a dollar stablecoin falling below 1 USD."],["stablecoin","Stablecoin","A stablecoin is a cryptocurrency designed to keep a steady value, usually 1 US dollar, by being backed by reserves such as cash and treasury bills, by crypto collateral, or by other mechanisms."],["crypto-backed-stablecoin","Crypto-backed stablecoin","A crypto-backed stablecoin is a stablecoin issued against crypto collateral locked in smart contracts, usually worth more than the coins created, so the token can stay near 1 USD."],["synthetic-dollar","Synthetic dollar (delta-neutral stablecoin)","A synthetic dollar is a dollar-pegged token backed by a crypto asset plus an equal short futures position, so price moves cancel out and the combined value stays near 1 USD."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"Is USDT a dollar? Why is it everywhere when you buy crypto?"},"coin":null,"tool":null,"cta":false}});
